const serpData = $('SerpAPI — Busca Skincare').item.json;
const tavilyData = $input.first().json;
let contextParts = [];
if (serpData.organic_results && Array.isArray(serpData.organic_results)) {
  const serpSnippets = serpData.organic_results.slice(0, 10).map((r, i) => `[Fonte ${i+1}] ${r.title||''}:\n${r.snippet||''}\nURL: ${r.link||''}`).join('\n\n');
  contextParts.push('=== Resultados SerpAPI ===\n' + serpSnippets);
}
if (tavilyData.results && Array.isArray(tavilyData.results)) {
  const tavilySnippets = tavilyData.results.slice(0, 5).map((r, i) => `[Tavily ${i+1}] ${r.title||''}:\n${r.content||''}\nURL: ${r.url||''}`).join('\n\n');
  contextParts.push('=== Resultados Tavily ===\n' + tavilySnippets);
}
const contexto_pesquisa = contextParts.join('\n\n');
const tema_semana = $('Set Tema da Semana').item.json.tema_semana;
const clima_semana = $('Set Tema da Semana').item.json.clima_semana;
return [{ json: { contexto_pesquisa, tema_semana, clima_semana } }];

const response = $input.first().json;
let html_content = '';
if (response.content && Array.isArray(response.content) && response.content.length > 0) {
  html_content = response.content[0].text || '';
} else {
  throw new Error('Claude API não retornou conteúdo esperado: ' + JSON.stringify(response));
}
const html_wrapped = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><style>body{font-family:'Georgia',serif;color:#3a2a1e;margin:40px;line-height:1.7;}h1{color:#8b5e3c;font-size:2em;border-bottom:2px solid #e8c9a0;padding-bottom:10px;}h2{color:#8b5e3c;font-size:1.5em;margin-top:2em;}h3{color:#a0714f;font-size:1.2em;}p{margin:0.8em 0;}ul{margin:0.5em 0 1em 1.5em;}li{margin:0.3em 0;}</style></head><body><h1>Refúgio da Pele — PDF Semanal</h1>${html_content}</body></html>`;
return [{ json: { html_content: html_wrapped, tema_semana: $('Set Tema da Semana').item.json.tema_semana } }];

// Calcula estrutura de pastas: Ano > Mês (pt-BR) > Semana XX
const now = new Date();
const meses = ['janeiro','fevereiro','marco','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const ano = now.getFullYear().toString();
const mes = meses[now.getMonth()];
const semana = String(Math.ceil(now.getDate() / 7)).padStart(2, '0');
const tema = $('Extrair Conteúdo Claude').item.json.tema_semana || 'sem-tema';
const nomeArquivo = `refugio-da-pele-${ano}-${mes}-semana${semana}.pdf`;
const nomePasta = `Semana ${semana}`;
return [{ json: { ano, mes, semana, nomeArquivo, nomePasta, tema } }];

const fileId = $input.first().json.id;
const pdf_url = `https://drive.google.com/file/d/${fileId}/view?usp=sharing`;
return [{ json: { pdf_url, fileId } }];

const htmlCompleto = $('Extrair Conteúdo Claude').item.json.html_content;
const tema = $('Set Tema da Semana').item.json.tema_semana || 'skincare';
const folderSemanaId = $input.first().json.id;

// Extract only Day 1 and Day 2 blocks
const bodyMatch = htmlCompleto.match(/<body[^>]*>([\s\S]*?)<\/body>/);
const bodyContent = bodyMatch ? bodyMatch[1] : htmlCompleto;
const diaMatches = [...bodyContent.matchAll(/<h2>Dia \d/gi)];
let teaserContent = '';
if (diaMatches.length >= 2) {
  const start = diaMatches[0].index;
  const end = diaMatches.length >= 3 ? diaMatches[2].index : bodyContent.length;
  teaserContent = bodyContent.substring(start, end);
} else {
  teaserContent = bodyContent.substring(0, Math.floor(bodyContent.length * 0.4));
}

