return [{ json: { html_gratuito: htmlGratuito, folderSemanaId, tema } }];

const now = new Date();
const meses = ['janeiro','fevereiro','marco','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
const ano = now.getFullYear().toString();
const mes = meses[now.getMonth()];
const semana = String(Math.ceil(now.getDate() / 7)).padStart(2, '0');
const folderSemanaId = $('Gerar HTML PDF Gratuito').item.json.folderSemanaId;
const nomeArquivo = `refugio-da-pele-GRATIS-${ano}-${mes}-semana${semana}.pdf`;
return [{ json: { nomeArquivo, folderSemanaId } }];

const fileId = $input.first().json.id;
const pdf_gratuito_url = `https://drive.google.com/file/d/${fileId}/view?usp=sharing`;
return [{ json: { pdf_gratuito_url, fileId } }];
